#[test]
fn test_infer_sort() {
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // Type of Prop is Type 1
    let prop = Expr::prop();
    let ty = tc.infer_type(&prop).unwrap();
    assert!(matches!(&ty.kind, ExprKind::Sort(_)));
}

#[test]
fn test_infer_sort_type_family_fvar() {
    use crate::level::Level;

    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    let u = Name::from_string("u");
    let v = Name::from_string("v");
    let alpha_sort = Expr::from_kind(ExprKind::Sort(Level::param(u.clone())));
    let alpha = tc.ctx_push(Name::from_string("alpha"), alpha_sort, BinderInfo::Implicit);
    let beta_type = Expr::pi(
        BinderInfo::Default,
        Expr::from_kind(ExprKind::FVar(alpha)),
        Expr::from_kind(ExprKind::Sort(Level::param(v.clone()))),
    );
    let beta = tc.ctx_push(Name::from_string("beta"), beta_type, BinderInfo::Implicit);

    let beta_expr = Expr::from_kind(ExprKind::FVar(beta));
    let beta_sort = tc.infer_sort(&beta_expr).unwrap();
    let expected = Level::imax(Level::param(u), Level::succ(Level::param(v)));
    assert_eq!(beta_sort, expected);
}

#[test]
fn test_infer_sort_squash_prop_returns_zero_level() {
    use crate::level::Level;

    let env = Environment::with_mode(CleanMode::Impredicative);
    let tc = TypeChecker::with_mode(&env, CleanMode::Impredicative);
    let squash_prop = Expr::from_kind(ExprKind::Squash(std::sync::Arc::new(Expr::prop())));

    let level = tc
        .infer_sort(&squash_prop)
        .expect("infer_sort should accept Squash(Prop) via SProp");

    assert_eq!(level, Level::zero());
}

