#[test]
fn test_infer_let_body_type_depends_on_bound_var() {
    // Regression test for FVar escape in Let type inference.
    // Without abstract_fvar before instantiate, the body type retains
    // dangling FVar references instead of substituting the let value.
    //
    // Lean 4 equivalent: `let x : Type := Prop in (fun (a : x) => a)`
    // Expected type: Prop → Prop
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // let x : Type := Prop in (λ (a : x), a)
    //   BVar(0) in lambda type = let-bound x
    //   BVar(0) in lambda body = lambda-bound a
    let let_expr = Expr::let_named(
        Name::anon(),
        Expr::type_(),                                                // x : Type
        Expr::prop(),                                                 // x := Prop
        Expr::lam(BinderInfo::Default, Expr::bvar(0), Expr::bvar(0)), // λ (a : x), a
        false,
    );

    let ty = tc.infer_type(&let_expr).unwrap();
    // After instantiation: Prop → Prop = Pi(Default, Prop, Prop)
    match &ty.kind {
        ExprKind::Pi(_, domain, codomain) => {
            assert!(domain.is_prop(), "domain should be Prop, got {domain:?}");
            assert!(
                codomain.is_prop(),
                "codomain should be Prop, got {codomain:?}"
            );
        }
        _ => panic!("Expected Pi type (Prop → Prop), got {ty:?}"),
    }
}

#[test]
fn test_infer_let_identity_non_dependent_body() {
    // Simpler Let case: body type does NOT depend on the let-bound variable.
    // let x : Type := Prop in x  →  type is Type
    // This complements test_infer_let_body_type_depends_on_bound_var above.
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    let let_expr = Expr::let_named(
        Name::anon(),
        Expr::type_(), // x : Type
        Expr::prop(),  // x := Prop
        Expr::bvar(0), // body = x
        false,
    );

    let ty = tc.infer_type(&let_expr).unwrap();
    // The body is x, whose declared type is Type.
    // abstract_fvar + instantiate on Type (no FVars) = Type.
    // Type = Sort(1). The body's type doesn't depend on x, so no FVar issue.
    match &ty.kind {
        ExprKind::Sort(l) => assert!(!l.is_zero(), "Expected Type (Sort 1+), got Prop"),
        _ => panic!("let x : Type := Prop in x should have type Type (Sort), got {ty:?}"),
    }
}

